//! Fixtures generated by ggml da8e2a54b919557b816b1c2beb432ccb766f7ce0 C decoders.
use dsx_core::{formats::dequant_row, gguf::GType};
#[test]
fn native_quant_matches_ggml_fixtures() {
    for (id, raw, expected) in [
        (
            10,
            include_bytes!("native-fixtures/q2_K.raw").as_slice(),
            include_bytes!("native-fixtures/q2_K.f32").as_slice(),
        ),
        (
            18,
            include_bytes!("native-fixtures/iq3_xxs.raw").as_slice(),
            include_bytes!("native-fixtures/iq3_xxs.f32").as_slice(),
        ),
    ] {
        let ty = GType::from_id(id).unwrap();
        let mut out = vec![0.; expected.len() / 4];
        dequant_row(ty, raw, &mut out);
        for (i, (v, bytes)) in out.iter().zip(expected.chunks_exact(4)).enumerate() {
            let want = f32::from_le_bytes(bytes.try_into().unwrap());
            assert_eq!(*v, want, "type {id}, element {i}");
        }
    }
}
